import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"Vertical Slice: API Keys & PAT (Machine-to-Machine)","description":"","frontmatter":{},"headers":[],"relativePath":"en/13-api-keys-pat.md","filePath":"en/13-api-keys-pat.md"}'),n={name:"en/13-api-keys-pat.md"};function o(r,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="vertical-slice-api-keys-pat-machine-to-machine" tabindex="-1">Vertical Slice: API Keys &amp; PAT (Machine-to-Machine) <a class="header-anchor" href="#vertical-slice-api-keys-pat-machine-to-machine" aria-label="Permalink to &quot;Vertical Slice: API Keys &amp; PAT (Machine-to-Machine)&quot;">​</a></h1><blockquote><p><strong>Machine-to-Machine (M2M) Authentication for Autonomous AI Agents, CLI tools, and CI/CD pipelines with SHA-256 hashing and multi-tenant isolation.</strong></p></blockquote><hr><h2 id="_1-slice-overview" tabindex="-1">1. Slice Overview <a class="header-anchor" href="#_1-slice-overview" aria-label="Permalink to &quot;1. Slice Overview&quot;">​</a></h2><p>The <code>apikeys</code> slice (<code>apps/api/src/slices/apikeys/</code>) provides SoftForge&#39;s official channel for programmatic and autonomous agent authentication:</p><ul><li><strong>First-Class M2M Authentication:</strong> Empowers external AI agents (e.g., Cursor, Claude Dev, AutoPR, GitHub Actions, Python/Go scripts) to perform operations on the API without relying on web browser sessions or short-lived JWT tokens.</li><li><strong>SHA-256 Cryptographic Hashing:</strong> The plaintext secret (<code>sf_live_...</code>) is generated with high cryptographic entropy (<code>secrets.token_urlsafe(32)</code>) and revealed <strong>only once</strong> upon creation. The database exclusively persists the SHA-256 hexadecimal digest (<code>hashed_key</code>).</li><li><strong>Visual Key Identification via Masked Prefix:</strong> Listing endpoints return a masked prefix (<code>key_prefix</code>, e.g., <code>sf_live_a1b2...9xyz</code>), allowing administrators to identify keys without exposing credentials.</li><li><strong>Configurable Expiration:</strong> Keys can be configured with an optional lifetime in days (<code>expires_in_days</code>) or set to never expire. Expired keys are rejected with HTTP 401 Unauthorized.</li><li><strong>Instant Revocation:</strong> Workspace administrators can immediately revoke compromised or obsolete keys, terminating API access instantly.</li><li><strong>Strict Multi-Tenant Isolation:</strong> Each API key belongs strictly to its originating workspace. Any attempt to access resources in another workspace is rejected with HTTP 403 Forbidden.</li><li><strong>Integrated Audit Trail &amp; Outbound Webhooks:</strong> Key creation (<code>api_key.created</code>) and revocation (<code>api_key.revoked</code>) events automatically trigger immutable audit logs and outbound webhooks.</li></ul><hr><h2 id="_2-m2m-authentication-sequence" tabindex="-1">2. M2M Authentication Sequence <a class="header-anchor" href="#_2-m2m-authentication-sequence" aria-label="Permalink to &quot;2. M2M Authentication Sequence&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    autonumber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    actor Agent as Autonomous AI Agent / CI Script</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant API as SoftForge API (FastAPI)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Auth as Auth Dependency (get_current_user)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Service as ApiKey Service</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as PostgreSQL Database (api_keys)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Resource as Endpoint (/projects)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Agent-&gt;&gt;API: GET /api/v1/workspaces/{id}/projects</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over Agent,API: Header &quot;X-API-Key: sf_live_...&quot; or &quot;Authorization: Bearer sf_live_...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;Auth: Inject get_current_user dependency</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Auth-&gt;&gt;Service: authenticate_api_key(session, raw_key)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Service: Calculate SHA-256 hash of incoming key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;DB: Query active key where hashed_key = digest</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DB--&gt;&gt;Service: Return ApiKey + Creator User</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Service: Verify is_revoked=False and expires_at &gt; now()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;DB: Update last_used_at = now()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service--&gt;&gt;Auth: Return creator User</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Auth-&gt;&gt;Resource: Proceed with authenticated user and workspace security check</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Resource--&gt;&gt;Agent: HTTP 200 OK (Projects data)</span></span></code></pre></div><hr><h2 id="_3-how-to-use-api-keys" tabindex="-1">3. How to Use API Keys <a class="header-anchor" href="#_3-how-to-use-api-keys" aria-label="Permalink to &quot;3. How to Use API Keys&quot;">​</a></h2><p>SoftForge supports two standard HTTP request headers:</p><h3 id="option-a-x-api-key-header-recommended-for-scripts-and-ai-agents" tabindex="-1">Option A: <code>X-API-Key</code> Header (Recommended for Scripts and AI Agents) <a class="header-anchor" href="#option-a-x-api-key-header-recommended-for-scripts-and-ai-agents" aria-label="Permalink to &quot;Option A: \`X-API-Key\` Header (Recommended for Scripts and AI Agents)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.softforge.redepronta.com/api/v1/workspaces/{workspace_id}/projects&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-API-Key: sf_live_YOUR_SECRET_KEY_HERE&quot;</span></span></code></pre></div><h3 id="option-b-authorization-bearer-header-rfc-6750-standard" tabindex="-1">Option B: <code>Authorization: Bearer</code> Header (RFC 6750 Standard) <a class="header-anchor" href="#option-b-authorization-bearer-header-rfc-6750-standard" aria-label="Permalink to &quot;Option B: \`Authorization: Bearer\` Header (RFC 6750 Standard)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.softforge.redepronta.com/api/v1/auth/me&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer sf_live_YOUR_SECRET_KEY_HERE&quot;</span></span></code></pre></div><hr><h2 id="_4-slice-endpoints" tabindex="-1">4. Slice Endpoints <a class="header-anchor" href="#_4-slice-endpoints" aria-label="Permalink to &quot;4. Slice Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Route</th><th style="text-align:left;">Description</th><th style="text-align:left;">Minimum Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{workspace_id}/api-keys</code></td><td style="text-align:left;">Generates a new API key and returns the raw secret</td><td style="text-align:left;"><code>Admin</code></td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{workspace_id}/api-keys</code></td><td style="text-align:left;">Lists registered API keys with masked prefixes</td><td style="text-align:left;"><code>Admin</code></td></tr><tr><td style="text-align:left;"><code>DELETE</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{workspace_id}/api-keys/{key_id}</code></td><td style="text-align:left;">Immediately revokes an API key</td><td style="text-align:left;"><code>Admin</code></td></tr></tbody></table><hr><h2 id="_5-automated-verification-testing" tabindex="-1">5. Automated Verification &amp; Testing <a class="header-anchor" href="#_5-automated-verification-testing" aria-label="Permalink to &quot;5. Automated Verification &amp; Testing&quot;">​</a></h2><p>The slice is covered with 100% deterministic Pytest test cases (<code>test_apikeys_slice.py</code>):</p><ol><li><strong>Generation and Hashing:</strong> Validates key structure, prefix formatting, and SHA-256 consistency.</li><li><strong>CRUD Lifecycle:</strong> Creation, masked listing, and revocation.</li><li><strong>Real-world Authentication &amp; Tenant Isolation:</strong> Verifies requests authenticated via <code>X-API-Key</code> and <code>Authorization: Bearer</code>, ensuring cross-workspace access attempts receive HTTP 403 Forbidden.</li><li><strong>Invalid Key Protection:</strong> Returns HTTP 401 Unauthorized for forged, revoked, or expired keys.</li></ol>`,23)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
